    }
    if (!best) {
        for (int i = 0; i < map->count; i++) {
            const sf_sym_t *s = &map->syms[i];
            if (!best || s->start < best->start) {
                best = s;
            }
        }
    }
    if (!best) {
        return -1;
    }
    strncpy(sym_out, best->name, 127);
    sym_out[127] = '\0';
    *off_out = pc - best->start;
